sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);
	
	function TestCase_IsOotbRecord(grRecord,vExpected)
	{
		function TestCase_IsOotbRecord_CheckResult(vInput,vExpected,vResult)
		{
			return (vExpected == vResult);
		}
		
		test.TestCase(
			'Function IsOotbRecord()',
			IsOotbRecord,
			{
				'grRecord': grRecord
			},
			vExpected,
			TestCase_IsOotbRecord_CheckResult);
	}

	var testdata = new x_snc_devtools.TestDataAPI('ATF.DEVTOOLS');
		
	TestCase_IsOotbRecord(null,false);
	TestCase_IsOotbRecord(undefined,false);
	TestCase_IsOotbRecord({},false);
	TestCase_IsOotbRecord('TEST',false);	
	TestCase_IsOotbRecord(GetAppRecord('x_snc_devtools'),false);

	var grGlobalRecord = new GlideRecord('sys_script');
	grGlobalRecord.initialize();
	grGlobalRecord.name = 'TEST';
	grGlobalRecord.collection = 'incident';
	grGlobalRecord.sys_created_by = 'admin';
	grGlobalRecord.sys_scope = 'global';
	var strGlobalRecordSysId = GlideRecordInsert(grGlobalRecord);

	TestCase_IsOotbRecord(GetRecord('sys_script',strGlobalRecordSysId),false);	

	TestCase_IsOotbRecord(GetRecord('sys_script','226f34420a04bf070072e884fd291ed3'),true);
	TestCase_IsOotbRecord(GetRecord('sys_script','6a2e9d1453e80010833addeeff7b124f'),true);
	TestCase_IsOotbRecord(GetRecord('sys_documentation','0f0495d353c321103296ddeeff7b121d'),true);



	var strAppSysId = AppCreate('Test Alpha','scoped','x_test_alpha');

	

	test.Log('Testing the OOTB detection heuristics on a new Script Include...');
	var strScriptIncludeSysId = testdata.CreateScriptInclude(
		strAppSysId,
		'Alpha1',
		'function Test_Alpha1() {}', '', 'This is a test');


	RecordSetValue('sys_script_include',strScriptIncludeSysId,'sys_policy','',true);
	RecordSetValue('sys_script_include',strScriptIncludeSysId,'sys_created_by','admin',true);
	RecordSetValue('sys_script_include',strScriptIncludeSysId,'sys_created_on','2026-01-01 00:00:00',true);
	RecordSetValue('sys_script_include',strScriptIncludeSysId,'sys_scope',strAppSysId,true);
	RecordSetValue('sys_script_include',strScriptIncludeSysId,'sys_package',strAppSysId,true);
	TestCase_IsOotbRecord(GetRecord('sys_script_include',strScriptIncludeSysId),false);

	RecordSetValue('sys_script_include',strScriptIncludeSysId,'sys_created_by','system',true);
	TestCase_IsOotbRecord(GetRecord('sys_script_include',strScriptIncludeSysId),true);

	RecordSetValue('sys_script_include',strScriptIncludeSysId,'sys_created_by','@@snc_write_audit@@',true);
	TestCase_IsOotbRecord(GetRecord('sys_script_include',strScriptIncludeSysId),false);

	RecordSetValue('sys_script_include',strScriptIncludeSysId,'sys_created_by','admin',true);
	RecordSetValue('sys_script_include',strScriptIncludeSysId,'sys_policy','read',true);
	TestCase_IsOotbRecord(GetRecord('sys_script_include',strScriptIncludeSysId),true);

	RecordSetValue('sys_script_include',strScriptIncludeSysId,'sys_policy','',true);
	TestCase_IsOotbRecord(GetRecord('sys_script_include',strScriptIncludeSysId),false);

	RecordSetValue('sys_script_include',strScriptIncludeSysId,'sys_created_on','',true);
	TestCase_IsOotbRecord(GetRecord('sys_script_include',strScriptIncludeSysId),true);

	RecordSetValue('sys_script_include',strScriptIncludeSysId,'sys_created_on','2026-01-01 00:00:00',true);
	TestCase_IsOotbRecord(GetRecord('sys_script_include',strScriptIncludeSysId),false);

	RecordSetValue('sys_script_include',strScriptIncludeSysId,'sys_package','global',true);
	TestCase_IsOotbRecord(GetRecord('sys_script_include',strScriptIncludeSysId),true);

	RecordSetValue('sys_script_include',strScriptIncludeSysId,'sys_package','',true);
	TestCase_IsOotbRecord(GetRecord('sys_script_include',strScriptIncludeSysId),false);

	RecordSetValue('sys_script_include',strScriptIncludeSysId,'sys_package',strAppSysId,true);
	TestCase_IsOotbRecord(GetRecord('sys_script_include',strScriptIncludeSysId),false);

	test.Log('Creating a table in the test application...');
	var strTableSysId = TableCreate(strAppSysId,'test_ootb','Test OOTB','');
	if (IsValidSysId(strTableSysId) == false)
	{
		test.Log('Failed to create the test table.');
		test.SetResult(false);
		return test.GetResult();
	}

	test.Log('Testing custom Field Labels created by system...');
	var grDocumentation = new GlideRecord('sys_documentation');
	grDocumentation.initialize();
	grDocumentation.name = 'x_test_alpha_test_ootb';
	grDocumentation.element = 'x_test_alpha_test';
	grDocumentation.language = 'en';
	grDocumentation.label = 'Test';
	grDocumentation.sys_scope = strAppSysId;
	grDocumentation.sys_package = strAppSysId;
	grDocumentation.sys_policy = '';
	grDocumentation.sys_created_by = 'admin';
	grDocumentation.sys_created_on = '2026-01-01 00:00:00';
	var strDocumentationSysId = GlideRecordInsert(grDocumentation,true);

	if (IsValidSysId(strDocumentationSysId) == false)
	{
		test.Log('Failed to create the test Field Label.');
		test.SetResult(false);
		return test.GetResult();
	}

	TestCase_IsOotbRecord(GetRecord('sys_documentation',strDocumentationSysId),false);

	RecordSetValue('sys_documentation',strDocumentationSysId,'sys_created_by','system',true);
	TestCase_IsOotbRecord(GetRecord('sys_documentation',strDocumentationSysId),false);

	// Positive control: the scoped-element exception no longer applies.
	RecordSetValue('sys_documentation',strDocumentationSysId,'element','test',true);
	TestCase_IsOotbRecord(GetRecord('sys_documentation',strDocumentationSysId),true);

	RecordSetValue('sys_documentation',strDocumentationSysId,'element','u_test',true);
	TestCase_IsOotbRecord(GetRecord('sys_documentation',strDocumentationSysId),false);

	test.Log('Testing a custom Dictionary Entry created by system...');
	var grDictionary = new GlideRecord('sys_dictionary');
	grDictionary.initialize();
	grDictionary.name = 'x_test_alpha_test_ootb';
	grDictionary.element = 'u_test';
	grDictionary.column_label = 'Test';
	grDictionary.internal_type = 'string';
	grDictionary.max_length = 40;
	grDictionary.sys_scope = strAppSysId;
	grDictionary.sys_package = strAppSysId;
	grDictionary.sys_policy = '';
	grDictionary.sys_created_by = 'system';
	grDictionary.sys_created_on = '2026-01-01 00:00:00';
	var strDictionarySysId = GlideRecordInsert(grDictionary,true);

	if (IsValidSysId(strDictionarySysId) == false)
	{
		test.Log('Failed to create the test Dictionary Entry.');
		test.SetResult(false);
		return test.GetResult();
	}

	TestCase_IsOotbRecord(GetRecord('sys_dictionary',strDictionarySysId),false);

	test.Log('Testing a record that is not derived from sys_metadata...');
	var strCompanySysId = testdata.CreateCompany('COMPANY1');
	if (IsValidSysId(strCompanySysId) == false)
	{
		test.Log('Failed to create the test company.');
		test.SetResult(false);
		return test.GetResult();
	}

	RecordSetValue('core_company',strCompanySysId,'sys_created_by','system',true);
	TestCase_IsOotbRecord(GetRecord('core_company',strCompanySysId),false);


	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
